SELECT COALESCE(MAX(report_version_no), 0) + 1
FROM acc_acceptance_report_version
WHERE tenant_id = #{query.tenantId}
  AND acceptance_id = #{query.acceptanceId}
  AND deleted = b'0'

SELECT *
FROM acc_acceptance_report_version
WHERE tenant_id = #{query.tenantId}
  AND acceptance_id = #{query.acceptanceId}
  AND id = #{query.reportVersionId}
  AND deleted = b'0'
FOR UPDATE

SELECT r.id FROM acc_acceptance_report_version r JOIN acc_acceptance a ON a.id=r.acceptance_id AND a.tenant_id=r.tenant_id AND a.deleted=0
WHERE r.tenant_id=#{query.tenantId} AND a.project_id=#{query.projectId} AND r.deleted=0
  AND r.report_status IN ('EFFECTIVE','SUPERSEDED','REVOKED')
AND r.report_status='EFFECTIVE'
AND r.id > #{query.afterId}



            AND r.acceptance_id IN #{id}

        AND 1=0


ORDER BY r.id ASC LIMIT #{query.limit}
